<?php
$admin_title='Identidade do Site'; include __DIR__.'/includes/header.php'; $msg='';$erro='';
function upload_identity_file(array $file,string $prefix,array $allowed): ?string {if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if(($file['error']??1)!==UPLOAD_ERR_OK||($file['size']??0)>2*1024*1024)throw new RuntimeException('O arquivo deve ter no máximo 2 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($allowed[$mime]))throw new RuntimeException('Formato de arquivo não permitido.');$dir=__DIR__.'/../assets/img/uploads';if(!is_dir($dir))mkdir($dir,0755,true);if(!is_writable($dir))throw new RuntimeException('A pasta de uploads não permite gravação.');$name=$prefix.'_'.bin2hex(random_bytes(7)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Não foi possível salvar o arquivo.');return 'assets/img/uploads/'.$name;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){if(!verify_csrf($_POST['csrf_token']??null))$erro='Token de segurança inválido.';else{$nome=trim($_POST['site_name']??'');$tagline=trim($_POST['site_tagline']??'');$values=['site_logo'=>setting($pdo,'site_logo',''),'site_logo_compacto'=>setting($pdo,'site_logo_compacto',''),'site_favicon'=>setting($pdo,'site_favicon','')];try{$values['site_logo']=upload_identity_file($_FILES['logo']??[],'logo',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/svg+xml'=>'svg'])??$values['site_logo'];$values['site_logo_compacto']=upload_identity_file($_FILES['logo_compacto']??[],'logo_mobile',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/svg+xml'=>'svg'])??$values['site_logo_compacto'];$values['site_favicon']=upload_identity_file($_FILES['favicon']??[],'favicon',['image/x-icon'=>'ico','image/vnd.microsoft.icon'=>'ico','image/png'=>'png','image/svg+xml'=>'svg'])??$values['site_favicon'];}catch(Throwable $ex){$erro=$ex->getMessage();}if(!$erro&&$nome!==''){save_setting($pdo,'site_name',$nome);save_setting($pdo,'site_tagline',$tagline);foreach($values as $key=>$value)save_setting($pdo,$key,$value);$msg='Identidade atualizada com sucesso.';}}}
?><main class="admin-content"><div class="admin-heading"><div><h1>Identidade do site</h1><p class="muted">Nome, logos e favicon usados no site público e no menu responsivo.</p></div></div><?php if($msg): ?><div class="notice success"><?= e($msg) ?></div><?php endif; ?><?php if($erro): ?><div class="notice error"><?= e($erro) ?></div><?php endif; ?><div class="admin-panel"><form class="admin-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Nome do site<input name="site_name" required value="<?= e(setting($pdo,'site_name','Banco de Negócios')) ?>"></label><label>Slogan<input name="site_tagline" value="<?= e(setting($pdo,'site_tagline','Conectando oportunidades')) ?>"></label><div class="form-grid-2"><label>Logo principal<input type="file" name="logo" accept="image/jpeg,image/png,image/webp,image/svg+xml"><small class="muted">Cabeçalho desktop · até 2 MB.</small></label><label>Logo compacto<input type="file" name="logo_compacto" accept="image/jpeg,image/png,image/webp,image/svg+xml"><small class="muted">Usado em telas menores · até 2 MB.</small></label></div><label>Favicon<input type="file" name="favicon" accept="image/x-icon,image/png,image/svg+xml"><small class="muted">Ícone da aba do navegador · até 2 MB.</small></label><div class="identity-previews"><?php foreach(['site_logo'=>'Logo atual','site_logo_compacto'=>'Logo compacto atual','site_favicon'=>'Favicon atual'] as $key=>$label): if(setting($pdo,$key,'')): ?><figure><img src="../<?= e(setting($pdo,$key,'')) ?>" alt="<?= e($label) ?>"><figcaption><?= e($label) ?></figcaption></figure><?php endif; endforeach; ?></div><button class="btn btn-primary">Salvar identidade</button></form></div></main><?php include __DIR__.'/includes/footer.php'; ?>
